practice.solution:
package main

import "fmt"

const (
	Cheese = 1 << iota
	Ham
	Olives
	Peppers
)

func main() {
	var mask uint8
	fmt.Scan(&mask)
	if mask&Cheese != 0 {
		fmt.Println("Cheese")
	}
	if mask&Ham != 0 {
		fmt.Println("Ham")
	}
	if mask&Olives != 0 {
		fmt.Println("Olives")
	}
	if mask&Peppers != 0 {
		fmt.Println("Peppers")
	}
	mask |= Olives
	mask &^= Ham
	fmt.Printf("%04b\n", mask)
}

