package main

import (
	"fmt"
	"math/bits"
)

func main() {
	single := 0
	for {
		var n int
		if _, err := fmt.Scan(&n); err != nil {
			break
		}
		single ^= n
	}
	isPow := single > 0 && single&(single-1) == 0
	fmt.Println(single, bits.OnesCount(uint(single)), bits.Len(uint(single)), isPow)
}

